+/**
+ * @brief Distrugge una tabella del TRIE della zona cow.
+ *
+ * @param f	indirizzo fisico della tabella
+ * @param l	livello della tabella (1 = tabella di pagina, >1 = tabella intermedia)
+ */
+void distruggi_cow_tab(paddr f, natl l)
+{
+	natw nshared = vdf[f / DIM_PAGINA].nshared;
+	if (nshared > 0)
+		return;
+	if (l > 1) {
+		for (natl i = 0; i < 512; i++) {
+			tab_entry& e = get_entry(f, i);
+			if (e & BIT_P) {
+				paddr next = extr_IND_FISICO(e);
+				if (get_ref(next) == 0)
+					rilascia_tab(next);
+				else
+					distruggi_cow_tab(next, l - 1);
+			}
+		}
+	}
+	rilascia_tab(f);
+}
